INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(92792, 'ruRU', 'Прости моих внучек. Они думают, что должны защищать меня от каждого $r $c, забредающего в мои пруды.$b$bЧто ж, продолжай.', '', 24330),
(92793, 'ruRU', '<Положите руку на рог Сенегоса.>', '', 24330),
(92795, 'ruRU', 'Не спеши оплакивать меня, звёздный свет. Подари мне это последнее приключение.', '', 24330),
(92796, 'ruRU', 'Нам стоит вернуться к дедушке.', '', 24330),
(92797, 'ruRU', 'Вернёмся в Лазурное пристанище!', '', 24330),
(92798, 'ruRU', '<Перед вами стоит... не сам Сенегос, а его магическая проекция. Он выглядит сильным, уверенным и жизнерадостным. Это не тот увядающий дракон, которого вы видели томящимся в пруду.>', '', 24330),
(92823, 'ruRU', 'Я готов отправляться, как только скажешь, $n.', '', 24330),
(92824, 'ruRU', 'Тогда поспешим.', '', 24330),
(92825, 'ruRU', 'Очень хорошо. Встретимся у Верховного лорда. ((Граян выбегает наружу))', '', 24330),
(92826, 'ruRU', 'Нет. НЕТ! Я больше не потерплю неудач!', '', 24330),
(92829, 'ruRU', 'Я встречу тебя снаружи и подготовлю наших скакунов. Я создал Орден Серебряной Длани, чтобы победить Пылающий Легион — это будет его первый бой.((Тирион выходит наружу))', '', 24330),
(92835, 'ruRU', 'Вы поражены эффектом |TInterface\\Icons\\Spell_Shadow_ChillTouch.blp:20|t |cFFFF0404|Hspell:179977|h[Прикосновение рока]|h|r!', '', 24330),
(92849, 'ruRU', 'Мы отправимся по твоей команде, друг.', '', 24330),
(92851, 'ruRU', 'Ба, эти пушки БЕСПОЛЕЗНЫ! Встречай наше новейшее творение — орка Скверны!', '', 24330),
(92852, 'ruRU', 'Легион думает, что нам конец. Мы покажем им, как они ошибаются.', '', 24330),
(92854, 'ruRU', 'Вход', '', 24330),
(92855, 'ruRU', 'Аах, мой друг. Мой добрый, надёжный друг $n.$b$bУ тебя случайно не найдётся при себе маны-кристаллов?$b$bПослушай, друг. Если тебе когда-нибудь что-то понадобится — подчёркиваю, ЧТО УГОДНО — просто приходи поговорить со своим верным другом Рунасом. Я решу все твои проблемы. На меня можно положиться.$b$bКонечно, если бы мне что-то понадобилось, полагаю, ты бы тоже помог мне, верно? Например, если бы мне понадобился мана-кристалл или что-то подобное, ты бы отдал его мне?', '', 24330),
(92856, 'ruRU', 'Просто... просто веди, Рунас.', '', 24330),
(92866, 'ruRU', 'Дополнительная цель открыта!\n|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA1.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA2.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA3.blp:64|t\n|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA5.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA6.blp:64|t|TINTERFACE\\GLUES\\CREDITS\\CrystalSong1TGA7.blp:64|t\n|cFFFFFFFFЛей-руины Зарчинара|r', '', 24330),
(92867, 'ruRU', 'Какого чёрта ты творишь?', '', 24330),
(92868, 'ruRU', 'Ты не знаешь, кто я?', '', 24330),
(92869, 'ruRU', 'Я сдаюсь. Прошу, друг мой, прости меня. Мне действительно, искренне жаль.', '', 24330),
(92870, 'ruRU', 'Питаться такой необузданной энергией... это затуманивает рассудок.', '', 24330),
(92871, 'ruRU', 'Надеюсь, ты сможешь увидеть не только мои рваные одежды и отчаянное поведение. Я не чудовище.', '', 24330),
(92872, 'ruRU', 'Иди вперёд, друг мой. Я останусь здесь.', '', 24330),
(92873, 'ruRU', 'Спасибо тебе, друг мой, за то, что мои последние часы обрели хоть какой-то смысл.', '', 24330),
(92874, 'ruRU', 'Смотри. Я докажу тебе это. Я не просто какой-то обезумевший от маны УРОД, как остальные эти несчастные.', '', 24330),
(92875, 'ruRU', 'Оо, смотри! Мана-кристалл! Всего один глоточек.', '', 24330),
(92876, 'ruRU', 'Думаю... возможно, пришло время попрощаться.', '', 24330),
(92877, 'ruRU', 'Весьма впечатляющее оружие, друг мой!', '', 24330),
(92878, 'ruRU', 'Я... я больше не вижу тебя.', '', 24330),
(92879, 'ruRU', 'Кто это?', '', 24330),
(92880, 'ruRU', 'Меня зовут Рунас, сын Индаррила, некогда из Сурамара. Рад знакомству.', '', 24330);
